const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    logout(state) {
      state.user = null;
      state.tokens = null;
      state.isAuthenticated = false;
      storage.removeProfile();
    },
    clearError(state) {
      state.error = null;
    },
    initializeAuth(state) {
      const profile = storage.getProfile();
      if (profile) {
        state.user = profile.user;
        state.tokens = profile.tokens;
        state.isAuthenticated = true;
      }
    },
  },
  extraReducers: (builder) => {
    // Register
    builder.addCase(registerUser.pending, (state) => {
      state.loading = true;
      state.error = null;
    });
    builder.addCase(registerUser.fulfilled, (state, action: PayloadAction<RegisterResponse>) => {
      state.loading = false;
      state.user = action.payload.user;
      state.isAuthenticated = false; // User not authenticated until email verification
    });
    builder.addCase(registerUser.rejected, (state, action) => {
      state.loading = false;
      state.error = action.payload?.message || 'Registration failed';
    });

    // Login
    builder.addCase(loginUser.pending, (state) => {
      state.loading = true;
      state.error = null;
    });
    builder.addCase(loginUser.fulfilled, (state, action: PayloadAction<AuthResponse>) => {
      state.loading = false;
      state.user = action.payload.user;
      state.tokens = {
        access: action.payload.access,
        refresh: action.payload.refresh,
      };
      state.isAuthenticated = true;

      storage.setProfile({
        user: action.payload.user,
        tokens: {
          access: action.payload.access,
          refresh: action.payload.refresh,
        }
      });
    });
    builder.addCase(loginUser.rejected, (state, action) => {
      state.loading = false;
      state.error = action.payload?.message || 'Login failed';
    });

    // Forgot Password
    builder.addCase(forgotPassword.pending, (state) => {
      state.loading = true;
      state.error = null;
    });
    builder.addCase(forgotPassword.fulfilled, (state) => {
      state.loading = false;
    });
    builder.addCase(forgotPassword.rejected, (state, action) => {
      state.loading = false;
      state.error = action.payload?.message || 'Password reset failed';
    });

    // Reset Password
    builder.addCase(resetPassword.pending, (state) => {
      state.loading = true;
      state.error = null;
    });
    builder.addCase(resetPassword.fulfilled, (state) => {
      state.loading = false;
    });
    builder.addCase(resetPassword.rejected, (state, action) => {
      state.loading = false;
      state.error = action.payload?.message || 'Password reset failed';
    });

    // Verify OTP
    builder.addCase(verifyOTP.pending, (state) => {
      state.loading = true;
      state.error = null;
    });
    builder.addCase(verifyOTP.fulfilled, (state, action: PayloadAction<OTPResponse>) => {
      state.loading = false;
      if (state.user) {
        state.user.is_verified = action.payload.user.is_verified;
        // Update stored profile if it exists
        const profile = storage.getProfile();
        if (profile) {
          storage.setProfile({
            ...profile,
            user: {
              ...profile.user,
              is_verified: action.payload.user.is_verified
            }
          });
        }
      }
    });
    builder.addCase(verifyOTP.rejected, (state, action) => {
      state.loading = false;
      state.error = action.payload?.message || 'OTP verification failed';
    });
  },
});

export const { logout, clearError, initializeAuth } = authSlice.actions;
export default authSlice.reducer;